const express = require('express');
const fetch = require('node-fetch');

const app = express();
const PORT = 3000;
const CROSSMINT_API_KEY = process.env.CROSSMINT_API_KEY;

// Middleware to parse JSON bodies
app.use(express.json());

// Health check endpoint
app.get('/health', (req, res) => {
  res.json({ status: 'ok' });
});

// Webhook purchase endpoint
app.post('/webhook/purchase', async (req, res) => {
  const { purchaseId, customerEmail, productName, amount } = req.body;

  // Validate required fields
  const requiredFields = ['purchaseId', 'customerEmail', 'productName', 'amount'];
  const missingFields = requiredFields.filter(field => !req.body[field]);

  if (missingFields.length > 0) {
    return res.status(400).json({
      error: 'Missing required fields',
      required: requiredFields
    });
  }

  try {
    // Mint NFT receipt via Crossmint API
    const crossmintResponse = await fetch(
      'https://staging.crossmint.com/api/2022-06-09/collections/default/nfts',
      {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'X-API-KEY': CROSSMINT_API_KEY
        },
        body: JSON.stringify({
          recipient: `email:${customerEmail}:polygon-amoy`,
          metadata: {
            name: `Receipt: ${productName}`,
            description: `Proof of purchase for order ${purchaseId}`,
            image: 'https://example.com/receipt.png'
          }
        })
      }
    );

    const crossmintData = await crossmintResponse.json();
    const actionId = crossmintData.id || 'mock-action';

    res.json({
      status: 'receipt_minted',
      purchaseId,
      actionId
    });
  } catch (error) {
    console.error('Error minting NFT:', error);
    res.status(500).json({
      error: 'Failed to mint NFT receipt',
      message: error.message
    });
  }
});

// Start server
app.listen(PORT, () => {
  console.log(`Webhook server listening on port ${PORT}`);
});

