const { spawn } = require('child_process');
const http = require('http');

// Start the server as a child process
const serverProcess = spawn('node', ['/home/user/webhook_server.js'], {
  env: { ...process.env, CROSSMINT_API_KEY: process.env.CROSSMINT_API_KEY || 'test-api-key' }
});

// Give the server time to start
setTimeout(async () => {
  const report = {
    health_check: false,
    webhook_response: null
  };

  // Test health endpoint
  try {
    const healthResponse = await makeRequest('GET', '/health', null);
    report.health_check = healthResponse && healthResponse.status === 'ok';
    console.log('Health check:', report.health_check);
  } catch (error) {
    console.error('Health check failed:', error.message);
  }

  // Test webhook purchase endpoint
  try {
    const purchasePayload = {
      purchaseId: 'test-purchase-123',
      customerEmail: 'test@example.com',
      productName: 'Test Product',
      amount: 99.99
    };
    const webhookResponse = await makeRequest('POST', '/webhook/purchase', purchasePayload);
    report.webhook_response = webhookResponse;
    console.log('Webhook response:', JSON.stringify(webhookResponse, null, 2));
  } catch (error) {
    console.error('Webhook test failed:', error.message);
    report.webhook_response = { error: error.message };
  }

  // Save report to file
  const fs = require('fs');
  fs.writeFileSync('/home/user/webhook_test_report.json', JSON.stringify(report, null, 2));
  console.log('Report saved to /home/user/webhook_test_report.json');

  // Kill the server process
  serverProcess.kill();
  process.exit(0);
}, 2000); // Wait 2 seconds for server to start

function makeRequest(method, path, body) {
  return new Promise((resolve, reject) => {
    const options = {
      hostname: 'localhost',
      port: 3000,
      path: path,
      method: method,
      headers: {}
    };

    if (body) {
      options.headers['Content-Type'] = 'application/json';
    }

    const req = http.request(options, (res) => {
      let data = '';

      res.on('data', (chunk) => {
        data += chunk;
      });

      res.on('end', () => {
        try {
          resolve(JSON.parse(data));
        } catch (error) {
          resolve(data);
        }
      });
    });

    req.on('error', (error) => {
      reject(error);
    });

    if (body) {
      req.write(JSON.stringify(body));
    }

    req.end();
  });
}

